# Complete actions generated by the upstream menu. QQ delivers these as normal
# messages from the clicker; the original plugin still checks its permissions.
_REVIEWED_ACTIONS = frozenset({
    '#营地wx全局登录', '#营地QQ全局登录',
    '#开启战绩推送', '#关闭战绩推送', '#开启上下线提醒',
    '#开启皮肤上新推送', '#关闭皮肤上新推送',
    '#开启王者公告推送', '#关闭王者公告推送',
})


def is_complete_callback(command):
    return isinstance(command, str) and (
        command in _REVIEWED_ACTIONS or command in _GOK_HELP_CALLBACKS or is_read_only_callback(command)
    )


_EXACT = frozenset({
    '#营地ID', '#王者ID', '#我的王者ID', '#绑定营地',
    '#战绩推送状态', '#谁在打游戏', '#皮肤上新', '#王者公告',
    '#王者帮助', '#查询战绩帮助', '#英雄相关帮助', '#皮肤帮助',
    '#营地观战帮助', '#营地消息帮助',
})
_READ_ONLY_PATTERNS = tuple(re.compile(pattern) for pattern in (
    r'#(?:王者主页|查询战绩|常用英雄|称号墙|皮肤墙|全部皮肤|缺皮肤|我的英雄)[0-9]{0,20}',
    r'#查询[0-9]{0,20}(?:排位|巅峰)?战绩[0-9]{0,20}',
    r'#(?:排位|巅峰)战绩[0-9]{0,20}',
    r'#(?:排位|巅峰)(?:总排名|排名)(?:刷新)?',
    r'#(?:排位|巅峰|赛季)表现[0-9]{0,20}(?:[sS][0-9]{1,3})?',
    r'#全部(?:排位|巅峰|赛季)表现[0-9]{0,20}(?: (?:all|[0-9]{1,3}))?',
    r'#(?:巅峰|段位)趋势[0-9]{0,20}(?: [0-9]{1,20})?',
    r'#英雄梯度(?:对抗路|中路|打野|发育路|游走)?',
    r'#(?:查战力|查战绩|查皮肤|英雄攻略|缺皮肤)[\u3400-\u9fffA-Za-z0-9·]{1,24}(?:\((?:法师|射手|辅助|坦克|刺客)\)|（(?:法师|射手|辅助|坦克|刺客)）)?',
))


def is_read_only_callback(command):
    if not isinstance(command, str) or not command or len(command) > 100:
        return False
    if any(ord(char) < 32 or ord(char) == 127 for char in command):
        return False
    return command in _EXACT or any(pattern.fullmatch(command) for pattern in _READ_ONLY_PATTERNS)
